class Solution {
public:
    int minJumps(vector<int>& nums) {
        int n = nums.size(), mx = *max_element(nums.begin(), nums.end());
        vector<int> spf(mx + 1);
        for (int i = 2; i <= mx; ++i) {
            if (!spf[i]) {
                spf[i] = i;
                if (1LL * i * i <= mx) {
                    for (int j = i * i; j <= mx; j += i)
                        if (!spf[j]) spf[j] = i;
                }
            }
        }
        unordered_map<int, vector<int>> at;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            while (x > 1) {
                int p = spf[x];
                at[p].push_back(i);
                while (x % p == 0) x /= p;
            }
        }
        vector<int> dist(n, -1);
        queue<int> q;
        q.push(0);
        dist[0] = 0;
        while (!q.empty()) {
            int i = q.front(); q.pop();
            if (i == n - 1) return dist[i];
            for (int j : {i - 1, i + 1}) {
                if (j >= 0 && j < n && dist[j] == -1) {
                    dist[j] = dist[i] + 1;
                    q.push(j);
                }
            }
            int p = nums[i];
            if (p >= 2 && spf[p] == p) {
                auto it = at.find(p);
                if (it != at.end()) {
                    for (int j : it->second) {
                        if (dist[j] == -1) {
                            dist[j] = dist[i] + 1;
                            q.push(j);
                        }
                    }
                    at.erase(it);
                }
            }
        }
        return -1;
    }
};
